-- 注意: JSON 列使用 JSONB；标识符统一双引号小写。
CREATE TABLE IF NOT EXISTS "sys_order" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "order_no" VARCHAR(32) NOT NULL,
    "customer_name" VARCHAR(64) NOT NULL,
    "amount" NUMERIC(18,2) DEFAULT 0.00 NOT NULL,
    "status" VARCHAR(16) DEFAULT 'NEW' NOT NULL,
    "remark" TEXT,
    "created_dept" VARCHAR(128),
    "created_at" TIMESTAMP NOT NULL,
    "created_by" VARCHAR(64),
    "updated_at" TIMESTAMP NOT NULL,
    "updated_by" VARCHAR(64),
    CONSTRAINT "pk_sys_order" PRIMARY KEY ("id"),
    CONSTRAINT "uk_sys_order_order_no" UNIQUE ("order_no")
);

COMMENT ON TABLE "sys_order" IS '订单主表';
COMMENT ON COLUMN "sys_order"."id" IS '主键 ID（雪花算法）';
COMMENT ON COLUMN "sys_order"."order_no" IS '订单号';
COMMENT ON COLUMN "sys_order"."customer_name" IS '客户名称';
COMMENT ON COLUMN "sys_order"."amount" IS '订单金额';
COMMENT ON COLUMN "sys_order"."status" IS '订单状态（枚举: NEW: 新建, PAID: 已支付, SHIPPED: 已发货）';
COMMENT ON COLUMN "sys_order"."remark" IS '备注';
COMMENT ON COLUMN "sys_order"."created_dept" IS '创建部门';
COMMENT ON COLUMN "sys_order"."created_at" IS '创建时间';
COMMENT ON COLUMN "sys_order"."created_by" IS '创建人';
COMMENT ON COLUMN "sys_order"."updated_at" IS '更新时间';
COMMENT ON COLUMN "sys_order"."updated_by" IS '更新人';

CREATE INDEX IF NOT EXISTS "idx_sys_order_customer_name" ON "sys_order" ("customer_name");
CREATE INDEX IF NOT EXISTS "idx_sys_order_status" ON "sys_order" ("status");
CREATE INDEX IF NOT EXISTS "idx_sys_order_remark" ON "sys_order" ("remark");
